import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, texture } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  const group = new Group();
  const timelines = [];

  // 1. Dimensions based on Atlas Region aspect ratio (512x320 -> 1.6)
  const width = 2.4;
  const height = 1.5;
  const geometry = new PlaneGeometry(width, height);

  // 2. Setup Engineered Gradient + Subtle Grain via TSL Node Material
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false
  });

  // Default color nodes: vertical gradient from surface (#0b0b10) to ink (#16161d)
  const uvNode = uv();
  const colSurface = vec3(0.043, 0.043, 0.063); // #0b0b10
  const colInk = vec3(0.086, 0.086, 0.114);     // #16161d
  const colAccent = vec3(1.0, 0.165, 0.22);      // #ff2a38

  // Base background gradient
  const bgGrad = mix(colInk, colSurface, uvNode.y);

  // Subtle accent hairline glow at bottom edge
  const edgeWeight = uvNode.y.oneMinus().pow(8.0);
  const finalBg = mix(bgGrad, colAccent, edgeWeight.mul(0.35));

  material.colorNode = finalBg;

  // Load and blend grain texture if available
  const imgUrl = config.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png';
  ctx.textureLoader.loadTexture(imgUrl).then((tex) => {
    tex.wrapS = ctx.THREE.RepeatWrapping;
    tex.wrapT = ctx.THREE.RepeatWrapping;

    // Low opacity grain blending
    const texNode = texture(tex, uvNode.mul(2.0));
    material.colorNode = mix(finalBg, finalBg.add(texNode.rgb.mul(0.12)), 0.6);
    material.needsUpdate = true;
  }).catch((err) => {
    console.warn('Could not load grain texture, falling back to clean gradient', err);
  });

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // 3. Text Element (Using standard bridging for text items or fallback)
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labelText = textItems[0]?.text ?? "Features 3";

  const textElement = ctx.fontAtlas.createText(labelText, {
    fontSize: 48,
    color: '#e8ecf2',
    align: 'center'
  });

  // Scale down and position above the textured plane
  textElement.scale.setScalar(0.0075);
  textElement.position.set(0, 0, 0.03);
  group.add(textElement);

  // 4. Subtle entrance/presence animation (weighted settle)
  group.position.y += 0.2;
  group.scale.set(0.9, 0.9, 0.9);

  const tl = gsap.timeline({ defaults: { ease: 'power4.out' } });
  tl.to(group.position, { y: 0, duration: 1.2 }, 0);
  tl.to(group.scale, { x: 1, y: 1, z: 1, duration: 1.2 }, 0);
  timelines.push(tl);

  // 5. Cleanup Hook
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    geometry.dispose();
    material.dispose();
    if (textElement.userData?.cleanup) {
      textElement.userData.cleanup();
    }
  };

  return group;
}
